import sys

def main():
    data = sys.stdin.read().split()
    n, k = int(data[0]), int(data[1])
    a = [int(x) for x in data[2:2 + n]]
    vals = sorted(set(a))

    def ok(x):
        cnt = 0
        i = 0
        while i < n:
            if a[i] <= x:
                cnt += 1
                i += 2
            else:
                i += 1
        return cnt >= k

    lo, hi = 0, len(vals) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if ok(vals[mid]):
            hi = mid
        else:
            lo = mid + 1
    print(vals[lo])

main()

